1	package wallet
2	
3	import (
4		"fmt"
5		"sync"
6		"time"
7	)
8	
9	// Wallet 是进程内的智能钱包。
10	//
11	// 所有方法都可被多个 goroutine 并发调用；每一次申请、结算或取消都在
12	// 同一把锁内原子完成，因此余额与共享累计额度不会被超扣，同一请求也
13	// 只会产生一个终态。状态仅在当前 Wallet 实例的生命周期内保留。
14	type Wallet struct {
15		mu sync.Mutex
16	
17		// now 可在同包测试中替换，默认使用 time.Now。
18		now func() time.Time
19	
20		accounts map[string]*account
21		sessions map[string]*session
22		policies map[string]*policy
23		// requests 以“使用账户编号 + 请求编号”为键，实现按使用账户的幂等。
24		requests map[requestKey]*request
25		ledger   []LedgerEntry
26	}
27	
28	type account struct {
29		id        string
30		available int64
31		reserved  int64
32		createdAt time.Time
33	}
34	
35	type session struct {
36		id        string
37		accountID string
38		deviceID  string
39		expiresAt time.Time
40		revoked   bool
41		createdAt time.Time
42	}
43	
44	type policy struct {
45		id              string
46		payerAccountID  string
47		allowedAccounts map[string]struct{}
48		operation       string
49		payee           string
50		startsAt        time.Time
51		endsAt          time.Time
52		maxPerRequest   int64
53		maxTotal        int64
54		reservedTotal   int64
55		spentTotal      int64
56	}
57	
58	type request struct {
59		policyID       string
60		requestID      string
61		accountID      string
62		payerAccountID string
63		operation      string
64		payee          string
65		estimatedFee   int64
66		actualFee      int64
67		state          RequestState
68		createdAt      time.Time
69		settledAt      time.Time
70	}
71	
72	type requestKey struct {
73		accountID string
74		requestID string
75	}
76	
77	// New 创建一个空钱包。
78	func New() *Wallet {
79		return &Wallet{
80			now:      time.Now,
81			accounts: make(map[string]*account),
82			sessions: make(map[string]*session),
83			policies: make(map[string]*policy),
84			requests: make(map[requestKey]*request),
85		}
86	}
87	
88	// CreateAccount 创建具有唯一编号和初始代付余额的账户。
89	//
90	// 金额为最小货币单位的整数；初始余额为负或编号重复时返回错误，
91	// 且不会改动任何已有资金记录。
92	func (w *Wallet) CreateAccount(id string, initialBalance int64) (AccountView, error) {
93		if id == "" {
94			return AccountView{}, ErrEmptyAccountID
95		}
96		if initialBalance < 0 {
97			return AccountView{}, fmt.Errorf("%w: initial balance must not be negative", ErrInvalidAmount)
98		}
99	
100		w.mu.Lock()
101		defer w.mu.Unlock()
102	
103		if _, ok := w.accounts[id]; ok {
104			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountExists, id)
105		}
106		now := w.now()
107		acc := &account{id: id, available: initialBalance, createdAt: now}
108		w.accounts[id] = acc
109		return acc.view(), nil
110	}
111	
112	// Account 查询账户视图；账户不存在时返回 ErrAccountNotFound。
113	func (w *Wallet) Account(id string) (AccountView, error) {
114		w.mu.Lock()
115		defer w.mu.Unlock()
116	
117		acc, ok := w.accounts[id]
118		if !ok {
119			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, id)
120		}
121		return acc.view(), nil
122	}
123	
124	// Balance 查询账户的可用余额与预留余额。
125	func (w *Wallet) Balance(id string) (Balances, error) {
126		view, err := w.Account(id)
127		if err != nil {
128			return Balances{}, err
129		}
130		return view.Balances, nil
131	}
132	
133	// CreateSession 为账户创建一个绑定设备、带到期时间的会话。
134	//
135	// 会话编号全局唯一；账户必须存在。
136	func (w *Wallet) CreateSession(id, accountID, deviceID string, expiresAt time.Time) (SessionView, error) {
137		if id == "" || accountID == "" || deviceID == "" {
138			return SessionView{}, fmt.Errorf("%w: session id, account id and device id are required", ErrInvalidArgument)
139		}
140	
141		w.mu.Lock()
142		defer w.mu.Unlock()
143	
144		if _, ok := w.accounts[accountID]; !ok {
145			return SessionView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, accountID)
146		}
147		if _, ok := w.sessions[id]; ok {
148			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionExists, id)
149		}
150		now := w.now()
151		sess := &session{
152			id:        id,
153			accountID: accountID,
154			deviceID:  deviceID,
155			expiresAt: expiresAt,
156			createdAt: now,
157		}
158		w.sessions[id] = sess
159		return sess.view(), nil
160	}
161	
162	// RevokeSession 主动吊销会话。会话不存在返回错误；重复吊销视为成功。
163	// 吊销后不再受理该会话的新申请，但已预留费用的请求仍可结算或取消。
164	func (w *Wallet) RevokeSession(id string) error {
165		w.mu.Lock()
166		defer w.mu.Unlock()
167	
168		sess, ok := w.sessions[id]
169		if !ok {
170			return fmt.Errorf("%w: %s", ErrSessionNotFound, id)
171		}
172		sess.revoked = true
173		return nil
174	}
175	
176	// Session 查询会话视图。
177	func (w *Wallet) Session(id string) (SessionView, error) {
178		w.mu.Lock()
179		defer w.mu.Unlock()
180	
181		sess, ok := w.sessions[id]
182		if !ok {
183			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
184		}
185		return sess.view(), nil
186	}
187	
188	// SavePolicy 保存（创建）一条代付策略。
189	//
190	// 出资账户和所有使用账户必须存在，限额必须为正，开始时间必须严格早于
191	// 结束时间，编号不得重复，否则拒绝保存并返回包装了具体原因的错误。
192	func (w *Wallet) SavePolicy(spec PolicySpec) error {
193		if spec.ID == "" {
194			return fmt.Errorf("%w: policy id is required", ErrPolicyInvalid)
195		}
196		if spec.Operation == "" || spec.Payee == "" {
197			return fmt.Errorf("%w: operation and payee are required", ErrPolicyInvalid)
198		}
199		if spec.MaxPerRequest <= 0 || spec.MaxTotal <= 0 {
200			return fmt.Errorf("%w: limits must be positive", ErrPolicyInvalid)
201		}
202		if !spec.StartsAt.Before(spec.EndsAt) {
203			return fmt.Errorf("%w: starts-at must be before ends-at", ErrPolicyInvalid)
204		}
205		if spec.PayerAccountID == "" || len(spec.AllowedAccountIDs) == 0 {
206			return fmt.Errorf("%w: payer account and at least one allowed account are required", ErrPolicyInvalid)
207		}
208	
209		w.mu.Lock()
210		defer w.mu.Unlock()
211	
212		if _, ok := w.policies[spec.ID]; ok {
213			return fmt.Errorf("%w: %s", ErrPolicyExists, spec.ID)
214		}
215		if _, ok := w.accounts[spec.PayerAccountID]; !ok {
216			return fmt.Errorf("%w: payer account %q: %w", ErrPolicyInvalid, spec.PayerAccountID, ErrAccountNotFound)
217		}
218		allowed := make(map[string]struct{}, len(spec.AllowedAccountIDs))
219		for _, id := range spec.AllowedAccountIDs {
220			if _, ok := w.accounts[id]; !ok {
221				return fmt.Errorf("%w: allowed account %q: %w", ErrPolicyInvalid, id, ErrAccountNotFound)
222			}
223			allowed[id] = struct{}{}
224		}
225	
226		w.policies[spec.ID] = &policy{
227			id:              spec.ID,
228			payerAccountID:  spec.PayerAccountID,
229			allowedAccounts: allowed,
230			operation:       spec.Operation,
231			payee:           spec.Payee,
232			startsAt:        spec.StartsAt,
233			endsAt:          spec.EndsAt,
234			maxPerRequest:   spec.MaxPerRequest,
235			maxTotal:        spec.MaxTotal,
236		}
237		return nil
238	}
239	
240	// Policy 查询策略视图，含当前预留中与已结算的累计金额。
241	func (w *Wallet) Policy(id string) (PolicyView, error) {
242		w.mu.Lock()
243		defer w.mu.Unlock()
244	
245		p, ok := w.policies[id]
246		if !ok {
247			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, id)
248		}
249		return p.view(), nil
250	}
251	
252	// Apply 提交一笔代付申请。
253	//
254	// 校验顺序为：申请字段 -> 使用账户 -> 会话（存在性、归属、设备、吊销、
255	// 到期）-> 幂等请求编号 -> 策略授权与额度 -> 出资账户余额。任一环节
256	// 失败都会在账本中留下带具体原因的拒绝记录，不产生任何扣款或预留。
257	//
258	// 同一使用账户以相同请求编号重复申请：策略、操作类型、收款方和预估
259	// 费用一致时直接返回已有请求（不再预留）；任一不同则返回 ErrConflict。
260	func (w *Wallet) Apply(in RequestInput) (RequestView, error) {
261		if in.EstimatedFee <= 0 {
262			return RequestView{}, w.reject(in, fmt.Errorf("%w: estimated fee must be positive", ErrInvalidAmount))
263		}
264		if in.AccountID == "" || in.SessionID == "" || in.DeviceID == "" || in.RequestID == "" || in.PolicyID == "" {
265			return RequestView{}, w.reject(in, fmt.Errorf("%w: account, session, device, policy and request id are required", ErrInvalidArgument))
266		}
267	
268		w.mu.Lock()
269		defer w.mu.Unlock()
270	
271		now := w.now()
272	
273		acc, ok := w.accounts[in.AccountID]
274		if !ok {
275			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrAccountNotFound, in.AccountID))
276		}
277		_ = acc
278	
279		sess, ok := w.sessions[in.SessionID]
280		if !ok {
281			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrSessionNotFound, in.SessionID))
282		}
283		if sess.accountID != in.AccountID {
284			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s belongs to account %s", ErrSessionAccountMismatch, sess.id, sess.accountID))
285		}
286		if sess.deviceID != in.DeviceID {
287			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s is bound to device %s", ErrSessionDeviceMismatch, sess.id, sess.deviceID))
288		}
289		if sess.revoked {
290			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s", ErrSessionRevoked, sess.id))
291		}
292		// 到期时刻及之后一律视为过期：[零值, ExpiresAt) 才有效。
293		if !now.Before(sess.expiresAt) {
294			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s expired at %s", ErrSessionExpired, sess.id, sess.expiresAt.Format(time.RFC3339)))
295		}
296	
297		key := requestKey{accountID: in.AccountID, requestID: in.RequestID}
298		if existing, ok := w.requests[key]; ok {
299			if existing.policyID == in.PolicyID &&
300				existing.operation == in.Operation &&
301				existing.payee == in.Payee &&
302				existing.estimatedFee == in.EstimatedFee {
303				// 幂等命中：直接返回已有结果，不再预留、不记账。
304				return existing.view(), nil
305			}
306			return RequestView{}, fmt.Errorf("%w: account %s request %s was already submitted with different content", ErrConflict, in.AccountID, in.RequestID)
307		}
308	
309		p, ok := w.policies[in.PolicyID]
310		if !ok {
311			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrPolicyNotFound, in.PolicyID))
312		}
313		if _, ok := p.allowedAccounts[in.AccountID]; !ok {
314			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: account %s is not allowed by policy %s", ErrPolicyDenied, in.AccountID, p.id))
315		}
316		if in.Operation != p.operation {
317			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: operation %q does not match policy %q", ErrPolicyDenied, in.Operation, p.operation))
318		}
319		if in.Payee != p.payee {
320			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payee %q does not match policy %q", ErrPolicyDenied, in.Payee, p.payee))
321		}
322		// 时间窗含开始、不含结束：[StartsAt, EndsAt)。
323		if now.Before(p.startsAt) || !now.Before(p.endsAt) {
324			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: current time %s is outside policy window [%s, %s)", ErrPolicyDenied,
325				now.Format(time.RFC3339), p.startsAt.Format(time.RFC3339), p.endsAt.Format(time.RFC3339)))
326		}
327		if in.EstimatedFee > p.maxPerRequest {
328			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d exceeds per-request limit %d", ErrQuotaExceeded, in.EstimatedFee, p.maxPerRequest))
329		}
330		// 预留中的费用同样占用共享累计额度。
331		if p.reservedTotal+p.spentTotal+in.EstimatedFee > p.maxTotal {
332			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
333				ErrQuotaExceeded, in.EstimatedFee, p.maxTotal, p.reservedTotal+p.spentTotal))
334		}
335	
336		payer, ok := w.accounts[p.payerAccountID]
337		if !ok {
338			// 保存策略时已校验，这里仅作防御。
339			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("payer account %s: %w", p.payerAccountID, ErrAccountNotFound))
340		}
341		if payer.available < in.EstimatedFee {
342			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, in.EstimatedFee))
343		}
344	
345		// 受理：从出资账户可用余额中预留预估费用。
346		payer.available -= in.EstimatedFee
347		payer.reserved += in.EstimatedFee
348		p.reservedTotal += in.EstimatedFee
349	
350		req := &request{
351			policyID:       p.id,
352			requestID:      in.RequestID,
353			accountID:      in.AccountID,
354			payerAccountID: payer.id,
355			operation:      in.Operation,
356			payee:          in.Payee,
357			estimatedFee:   in.EstimatedFee,
358			state:          RequestReserved,
359			createdAt:      now,
360		}
361		w.requests[key] = req
362		w.ledger = append(w.ledger, LedgerEntry{
363			Kind:      LedgerReserve,
364			AccountID: payer.id,
365			RequestID: in.RequestID,
366			Amount:    in.EstimatedFee,
367			Reason:    "reserve estimated fee",
368			At:        now,
369		})
370		return req.view(), nil
371	}
372	
373	// Settle 结算一笔已预留的代付请求。
374	//
375	// actualFee 允许为零但不得为负、不得超过预留的预估费用。结算时扣除
376	// 实际费用并把差额退回可用余额。以相同实际费用重复结算幂等返回，不
377	// 重复记账；不同实际费用返回 ErrConflict。已取消的请求不能结算。
378	func (w *Wallet) Settle(accountID, requestID string, actualFee int64) (RequestView, error) {
379		if actualFee < 0 {
380			return RequestView{}, fmt.Errorf("%w: actual fee must not be negative", ErrInvalidAmount)
381		}
382		w.mu.Lock()
383		defer w.mu.Unlock()
384	
385		req, p, err := w.lookupRequest(accountID, requestID)
386		if err != nil {
387			return RequestView{}, err
388		}
389		switch req.state {
390		case RequestSettled:
391			if req.actualFee == actualFee {
392				return req.view(), nil
393			}
394			return RequestView{}, fmt.Errorf("%w: request %s already settled with actual fee %d", ErrConflict, requestID, req.actualFee)
395		case RequestCancelled:
396			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadyCancelled, requestID)
397		}
398	
399		if actualFee > req.estimatedFee {
400			// 拒绝并保留预留。
401			return RequestView{}, fmt.Errorf("%w: actual %d > estimated %d for request %s", ErrSettleTooLarge, actualFee, req.estimatedFee, requestID)
402		}
403	
404		now := w.now()
405		payer := w.accounts[req.payerAccountID]
406		refund := req.estimatedFee - actualFee
407	
408		// 扣除实际费用、退回差额、释放共享额度。
409		payer.reserved -= req.estimatedFee
410		payer.available += refund
411		p.reservedTotal -= req.estimatedFee
412		p.spentTotal += actualFee
413	
414		req.state = RequestSettled
415		req.actualFee = actualFee
416		req.settledAt = now
417	
418		w.ledger = append(w.ledger, LedgerEntry{
419			Kind:      LedgerSettle,
420			AccountID: payer.id,
421			RequestID: requestID,
422			Amount:    actualFee,
423			Reason:    "settle actual fee",
424			At:        now,
425		})
426		if refund > 0 {
427			w.ledger = append(w.ledger, LedgerEntry{
428				Kind:      LedgerRefund,
429				AccountID: payer.id,
430				RequestID: requestID,
431				Amount:    refund,
432				Reason:    "refund estimated-minus-actual fee",
433				At:        now,
434			})
435		}
436		return req.view(), nil
437	}
438	
439	// Cancel 取消一笔尚未结算的代付请求，预留费用全部退回。
440	//
441	// 已结算的请求不能取消；重复取消幂等返回，不重复记账。
442	func (w *Wallet) Cancel(accountID, requestID string) (RequestView, error) {
443		w.mu.Lock()
444		defer w.mu.Unlock()
445	
446		req, p, err := w.lookupRequest(accountID, requestID)
447		if err != nil {
448			return RequestView{}, err
449		}
450		switch req.state {
451		case RequestCancelled:
452			return req.view(), nil
453		case RequestSettled:
454			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadySettled, requestID)
455		}
456	
457		now := w.now()
458		payer := w.accounts[req.payerAccountID]
459	
460		payer.reserved -= req.estimatedFee
461		payer.available += req.estimatedFee
462		p.reservedTotal -= req.estimatedFee
463	
464		req.state = RequestCancelled
465	
466		w.ledger = append(w.ledger, LedgerEntry{
467			Kind:      LedgerRefund,
468			AccountID: payer.id,
469			RequestID: requestID,
470			Amount:    req.estimatedFee,
471			Reason:    "refund reserved fee on cancel",
472			At:        now,
473		})
474		return req.view(), nil
475	}
476	
477	// Request 查询某使用账户下的代付请求。
478	func (w *Wallet) Request(accountID, requestID string) (RequestView, error) {
479		w.mu.Lock()
480		defer w.mu.Unlock()
481	
482		req, _, err := w.lookupRequest(accountID, requestID)
483		if err != nil {
484			return RequestView{}, err
485		}
486		return req.view(), nil
487	}
488	
489	// Ledger 返回全部账本记录的副本，按产生顺序排列。
490	// 申请被拒绝的记录（Kind 为 LedgerRejection）也包含在内并带有原因。
491	func (w *Wallet) Ledger() []LedgerEntry {
492		w.mu.Lock()
493		defer w.mu.Unlock()
494	
495		out := make([]LedgerEntry, len(w.ledger))
496		copy(out, w.ledger)
497		return out
498	}
499	
500	// AccountLedger 返回与指定出资账户资金变动相关的账本记录副本
501	// （预留、扣减、退回），不含与资金无关的拒绝记录。
502	func (w *Wallet) AccountLedger(accountID string) []LedgerEntry {
503		w.mu.Lock()
504		defer w.mu.Unlock()
505	
506		var out []LedgerEntry
507		for _, e := range w.ledger {
508			if e.AccountID == accountID {
509				out = append(out, e)
510			}
511		}
512		return out
513	}
514	
515	// lookupRequest 必须在持锁状态下调用。
516	func (w *Wallet) lookupRequest(accountID, requestID string) (*request, *policy, error) {
517		req, ok := w.requests[requestKey{accountID: accountID, requestID: requestID}]
518		if !ok {
519			return nil, nil, fmt.Errorf("%w: account %s request %s", ErrRequestNotFound, accountID, requestID)
520		}
521		return req, w.policies[req.policyID], nil
522	}
523	
524	// reject 记录无需持锁快速校验阶段的拒绝（当前没有此类调用，保留对称接口）。
525	func (w *Wallet) reject(in RequestInput, cause error) error {
526		w.mu.Lock()
527		defer w.mu.Unlock()
528		w.appendRejection(in, w.now(), cause)
529		return cause
530	}
531	
532	// rejectLocked 在持锁状态下记录拒绝原因并原样返回错误。
533	func (w *Wallet) rejectLocked(in RequestInput, at time.Time, cause error) error {
534		w.appendRejection(in, at, cause)
535		return cause
536	}
537	
538	// appendRejection 必须在持锁状态下调用。拒绝记录不携带资金账户，
539	// 只记录请求编号与具体原因，绝不产生金额变动。
540	func (w *Wallet) appendRejection(in RequestInput, at time.Time, cause error) {
541		w.ledger = append(w.ledger, LedgerEntry{
542			Kind:      LedgerRejection,
543			RequestID: in.RequestID,
544			Reason:    cause.Error(),
545			At:        at,
546		})
547	}
548	
549	func (a *account) view() AccountView {
550		return AccountView{
551			ID: a.id,
552			Balances: Balances{
553				Available: a.available,
554				Reserved:  a.reserved,
555			},
556			CreatedAt: a.createdAt,
557		}
558	}
559	
560	func (s *session) view() SessionView {
561		state := SessionActive
562		if s.revoked {
563			state = SessionRevoked
564		}
565		return SessionView{
566			ID:        s.id,
567			AccountID: s.accountID,
568			DeviceID:  s.deviceID,
569			ExpiresAt: s.expiresAt,
570			State:     state,
571			CreatedAt: s.createdAt,
572		}
573	}
574	
575	func (p *policy) view() PolicyView {
576		ids := make([]string, 0, len(p.allowedAccounts))
577		for id := range p.allowedAccounts {
578			ids = append(ids, id)
579		}
580		return PolicyView{
581			PolicySpec: PolicySpec{
582				ID:                p.id,
583				PayerAccountID:    p.payerAccountID,
584				AllowedAccountIDs: ids,
585				Operation:         p.operation,
586				Payee:             p.payee,
587				StartsAt:          p.startsAt,
588				EndsAt:            p.endsAt,
589				MaxPerRequest:     p.maxPerRequest,
590				MaxTotal:          p.maxTotal,
591			},
592			ReservedTotal: p.reservedTotal,
593			SpentTotal:    p.spentTotal,
594		}
595	}
596	
597	func (r *request) view() RequestView {
598		return RequestView{
599			PolicyID:       r.policyID,
600			RequestID:      r.requestID,
601			AccountID:      r.accountID,
602			PayerAccountID: r.payerAccountID,
603			Operation:      r.operation,
604			Payee:          r.payee,
605			EstimatedFee:   r.estimatedFee,
606			ActualFee:      r.actualFee,
607			State:          r.state,
608			CreatedAt:      r.createdAt,
609			SettledAt:      r.settledAt,
610		}
611	}
612

