297			t.Fatalf("balance after cancel = %+v", bal)
298		}
299		// 重复取消不重复记账。
300		entriesBefore := len(w.AccountLedger("payer"))
301		if _, err := w.Cancel("u1", "r1"); err != nil {
302			t.Fatalf("repeat cancel: %v", err)
303		}
304		if got := len(w.AccountLedger("payer")); got != entriesBefore {
305			t.Fatalf("ledger grew on repeat cancel")
306		}
307		// 已取消不能结算。
308		if _, err := w.Settle("u1", "r1", 0); !errors.Is(err, ErrAlreadyCancelled) {
309			t.Fatalf("settle cancelled err = %v", err)
310		}
311		// 已取消请求重复申请不能重新扣款。
312		before := len(w.Ledger())
313		if view, err := w.Apply(baseApply()); err != nil || view.State != RequestCancelled {
314			t.Fatalf("re-apply cancelled request: view=%+v err=%v", view, err)
315		}
316		if got := len(w.Ledger()); got != before {
317			t.Fatalf("re-apply cancelled request produced ledger entries: %d vs %d", got, before)
318		}
319		bal, _ = w.Balance("payer")
320		if bal != (Balances{Available: 100, Reserved: 0}) {
321			t.Fatalf("balance changed on re-apply: %+v", bal)
322		}
323	}
