344		for _, mutate := range []func(*RequestInput){
345			func(x *RequestInput) { x.PolicyID = "other" },
346			func(x *RequestInput) { x.Operation = "refund" },
347			func(x *RequestInput) { x.Payee = "other-shop" },
348			func(x *RequestInput) { x.EstimatedFee = 19 },
349		} {
350			conflict := in
351			mutate(&conflict)
352			// 不存在的策略会先报策略不存在；其余三类应报冲突。这里只验证“同号不同内容绝不二次预留”。
353			if _, err := w.Apply(conflict); err == nil {
354				t.Fatalf("conflicting re-apply accepted: %+v", conflict)
355			} else if !errors.Is(err, ErrConflict) && !errors.Is(err, ErrPolicyNotFound) {
356				t.Fatalf("conflicting re-apply err = %v", err)
357			}
358		}
359		bal, _ = w.Balance("payer")
