	req.state = RequestSettled
	req.actualFee = actualFee
	req.settledAt = now

	w.ledger = append(w.ledger, LedgerEntry{
		Kind:           LedgerSettle,
		AccountID:      payer.id,
		UsageAccountID: req.accountID,
		RequestID:      requestID,
		Amount:         actualFee,
		Reason:         "settle actual fee",
		At:             now,
	})
	if refund > 0 {
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:           LedgerRefund,
			AccountID:      payer.id,
			UsageAccountID: req.accountID,
			RequestID:      requestID,
			Amount:         refund,
			Reason:         "refund estimated-minus-actual fee",
			At:             now,
