448	// Approve 批准一笔待审批的代付请求。
449	//
450	// 必须使用策略出资账户绑定当前设备的有效会话（账户匹配、会话存在且归
451	// 属该账户、设备一致、未吊销且未到期），否则返回 ErrApprovalUnauthorized
452	// 且不改变请求。批准时会再次检查出资账户可用余额与策略共享剩余额度：
453	// 二者都足够才一次性预留全部预估费用并转为 RequestReserved；不足时返回
454	// 包装了 ErrInsufficientBalance 或 ErrQuotaExceeded 的具体原因，请求保留
455	// 待审批状态，期限内可再次批准。到达等待期限（含时刻本身）不能批准。
456	//
457	// 已获批并处于预留或结算状态的请求重复批准只幂等返回当前结果，不再
458	// 预留；已拒绝、过期或取消的请求不能再批准。
459	func (w *Wallet) Approve(accountID, requestID string, in ApprovalInput) (RequestView, error) {
460		w.mu.Lock()
461		defer w.mu.Unlock()
462	
463		req, p, err := w.lookupRequest(accountID, requestID)
464		if err != nil {
465			return RequestView{}, err
466		}
467		now := w.now()
468	
469		switch req.state {
470		case RequestReserved, RequestSettled:
471			// 已获批：只返回当前结果，不得再次预留。
472			return req.view(), nil
473		case RequestExpired:
474			return RequestView{}, fmt.Errorf("%w: request %s expired at %s", ErrApprovalDeadline, requestID, req.waitUntil.Format(time.RFC3339))
475		case RequestRejected:
476			return RequestView{}, fmt.Errorf("%w: request %s was rejected", ErrRequestNotPending, requestID)
477		case RequestCancelled:
478			return RequestView{}, fmt.Errorf("%w: request %s was cancelled", ErrRequestNotPending, requestID)
479		}
480	
481		// 待审批：先看期限，再校验审批身份。
482		if !now.Before(req.waitUntil) {
483			// lookupRequest 通常已完成流转，这里作边界兜底。
484			w.transitionToExpiredLocked(req, now)
485			return RequestView{}, fmt.Errorf("%w: request %s expired at %s", ErrApprovalDeadline, requestID, req.waitUntil.Format(time.RFC3339))
486		}
487		if err := w.checkApproverLocked(req, in, now); err != nil {
488			return RequestView{}, err
489		}
490	
491		payer := w.accounts[req.payerAccountID]
492		if payer.available < req.estimatedFee {
493			return RequestView{}, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, req.estimatedFee)
494		}
495		if p.reservedTotal+p.spentTotal+req.estimatedFee > p.maxTotal {
496			return RequestView{}, fmt.Errorf("%w: fee %d would exceed shared total limit %d (used %d)",
497				ErrQuotaExceeded, req.estimatedFee, p.maxTotal, p.reservedTotal+p.spentTotal)
498		}
499	
500		// 复查通过：批准状态留痕后一次性预留全部预估费用。
501		req.decidedAt = now
502		req.approver = in.ApproverAccountID
503		w.ledger = append(w.ledger, LedgerEntry{
504			Kind:           LedgerApproval,
505			UsageAccountID: req.accountID,
506			RequestID:      req.requestID,
507			Reason:         "pending request approved",
508			At:             now,
509		})
510		w.reserveLocked(req, p, payer, now, "reserve estimated fee on approval")
511		return req.view(), nil
512	}
