515	//
516	// 审批身份要求与 Approve 相同；reason 不能为空或全为空白，否则返回
517	// ErrInvalidArgument 且请求保持不变。拒绝不产生退款，请求进入
518	// RequestRejected 终态并记录原因。
519	//
520	// 以相同理由重复拒绝幂等返回、不重复留痕；理由不同返回 ErrConflict。
521	// 已批准（预留或结算）、已取消的请求不能再拒绝；已过期的请求按过期
522	// 处理。
523	func (w *Wallet) Reject(accountID, requestID string, in ApprovalInput) (RequestView, error) {
524		if strings.TrimSpace(in.Reason) == "" {
525			return RequestView{}, fmt.Errorf("%w: reject reason must not be blank", ErrInvalidArgument)
526		}
527	
528		w.mu.Lock()
529		defer w.mu.Unlock()
530	
531		req, _, err := w.lookupRequest(accountID, requestID)
532		if err != nil {
533			return RequestView{}, err
534		}
535		now := w.now()
536	
537		switch req.state {
538		case RequestRejected:
539			if req.rejectReason == in.Reason {
540				return req.view(), nil
541			}
542			return RequestView{}, fmt.Errorf("%w: request %s was rejected with reason %q", ErrConflict, requestID, req.rejectReason)
543		case RequestExpired:
544			return RequestView{}, fmt.Errorf("%w: request %s expired at %s", ErrApprovalDeadline, requestID, req.waitUntil.Format(time.RFC3339))
545		case RequestReserved, RequestSettled:
546			return RequestView{}, fmt.Errorf("%w: request %s was already approved", ErrRequestNotPending, requestID)
547		case RequestCancelled:
548			return RequestView{}, fmt.Errorf("%w: request %s was cancelled", ErrRequestNotPending, requestID)
549		}
550	
551		if !now.Before(req.waitUntil) {
552			w.transitionToExpiredLocked(req, now)
553			return RequestView{}, fmt.Errorf("%w: request %s expired at %s", ErrApprovalDeadline, requestID, req.waitUntil.Format(time.RFC3339))
554		}
555		if err := w.checkApproverLocked(req, in, now); err != nil {
556			return RequestView{}, err
557		}
558	
559		w.transitionToRejectedLocked(req, now, in.ApproverAccountID, in.Reason)
560		return req.view(), nil
561	}
562	
563	// checkApproverLocked 校验批准/拒绝身份：必须是出资账户绑定当前设备的
564	// 有效会话。任何不符都返回 ErrApprovalUnauthorized，不改变请求。
565	func (w *Wallet) checkApproverLocked(req *request, in ApprovalInput, now time.Time) error {
566		if in.ApproverAccountID == "" || in.SessionID == "" || in.DeviceID == "" {
567			return fmt.Errorf("%w: approver account, session and device are required", ErrApprovalUnauthorized)
568		}
569		if in.ApproverAccountID != req.payerAccountID {
570			return fmt.Errorf("%w: account %s is not the payer account %s", ErrApprovalUnauthorized, in.ApproverAccountID, req.payerAccountID)
571		}
572		sess, ok := w.sessions[in.SessionID]
573		if !ok {
574			return fmt.Errorf("%w: session %s: %w", ErrApprovalUnauthorized, in.SessionID, ErrSessionNotFound)
575		}
576		if sess.accountID != in.ApproverAccountID {
577			return fmt.Errorf("%w: session %s belongs to account %s", ErrApprovalUnauthorized, sess.id, sess.accountID)
578		}
579		if sess.deviceID != in.DeviceID {
580			return fmt.Errorf("%w: session %s is bound to device %s", ErrApprovalUnauthorized, sess.id, sess.deviceID)
581		}
582		if sess.revoked {
583			return fmt.Errorf("%w: session %s revoked", ErrApprovalUnauthorized, sess.id)
584		}
585		if !now.Before(sess.expiresAt) {
586			return fmt.Errorf("%w: session %s expired at %s", ErrApprovalUnauthorized, sess.id, sess.expiresAt.Format(time.RFC3339))
587		}
588		return nil
589	}
590	
591	// expireIfDueLocked 把到达等待期限的待审批请求流转为过期终态并留痕；
592	// 其他状态不做任何处理。必须在持锁状态下调用。
593	func (w *Wallet) expireIfDueLocked(req *request, now time.Time) {
594		if req.state != RequestPendingApproval {
595			return
596		}
597		if now.Before(req.waitUntil) {
598			return
599		}
600		w.transitionToExpiredLocked(req, now)
601	}
602	
603	// transitionToExpiredLocked 必须在持锁状态下调用。
604	func (w *Wallet) transitionToExpiredLocked(req *request, now time.Time) {
605		req.state = RequestExpired
606		req.decidedAt = now
607		w.ledger = append(w.ledger, LedgerEntry{
608			Kind:           LedgerExpired,
609			UsageAccountID: req.accountID,
610			RequestID:      req.requestID,
611			Reason:         "approval deadline passed without decision",
612			At:             now,
613		})
614	}
615	
616	// transitionToRejectedLocked 必须在持锁状态下调用。拒绝不涉及任何资金
617	// 变动；approver 为空表示由系统流转（如申请会话被吊销）。
618	func (w *Wallet) transitionToRejectedLocked(req *request, now time.Time, approver, reason string) {
619		req.state = RequestRejected
